  Lemma c2qf_run : forall regs0 regs u0 u1,
    c2qa_post u0 u1 regs -> (0 <= Z.lor u1 u0 < 2 ^ 64)%Z -> Z.lor u1 u0 = 0%Z ->
    exists regs',
